import{z as o,x as B,o as t,c as p,q as s,j as r,D as e,d as i,s as A,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"Rothschild–Stiglitz 保险筛选","description":"","frontmatter":{"title":"Rothschild–Stiglitz 保险筛选","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/rothschild-stiglitz.md","filePath":"econ/rothschild-stiglitz.md","lastUpdated":1791063341000}'),d={name:"econ/rothschild-stiglitz.md"};function h(c,E,D,m,S,u){const l=B("Mermaid");return t(),p("div",null,[E[2]||(E[2]=s('<h1 id="rothschild–stiglitz-保险筛选" tabindex="-1">Rothschild–Stiglitz 保险筛选 <a class="header-anchor" href="#rothschild–stiglitz-保险筛选" aria-label="Permalink to &quot;Rothschild–Stiglitz 保险筛选&quot;">​</a></h1><div class="epigraph"><p>竞争保险市场上，混同不是均衡；分离均衡可以不存在。</p><footer>—— Rothschild and Stiglitz, Equilibrium in Competitive Insurance Markets, Quarterly Journal of Economics 1976</footer></div><p><a href="/econ/spence-1973">上一课</a>（Spence 市场信号原文）。附录对照。主干<a href="/econ/screening-rent">筛选与信息租金</a>已用合同菜单与激励相容。本篇对照 <strong>Rothschild–Stiglitz 1976 原文</strong> 在保险市场上的尖锐结论：与 <a href="/econ/spence-1973">Spence</a> 的发送者信号不同，这里是保险公司（不知情方）先推出保单，知情的投保人自选；竞争加上逆向选择，均衡可能根本没有。不重写柠檬螺旋。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两类风险（高事故概率、低事故概率），每类有同一凹效用。保险公司风险中性、自由进入，只观察投保人选择的保单（保费、赔付），不观察类型。若只卖一张平均精算的混同保单，低风险等于补贴高风险。原文问：有没有一套保单，在竞争下既不亏损、又没有另一家公司能用新保单把它的客户挖走？</p><p>答案分两截。混同不是均衡：总能设计一份对低风险更有吸引力、对高风险无吸引力的偏离保单，把好风险挖走，留下高风险让原公司亏损。分离候选是：高风险拿全保险（其最优），低风险拿部分保险，刚好让高风险不愿假装低风险。但若低风险足够多，又会有人愿意提供接近混同的合同把低风险再挖走——于是分离也撑不住。均衡可以空。</p><p><span class="marginnote">直觉类比：只卖一张「平均价」保单，就像健身房按全体居民的平均受伤率定价：爱运动的人一算不划算走人，留下的净是容易受伤的，账立刻亏。平均化定价之下，愿意留下来的总是坏消息——这就是保单上的逆向选择。</span></p><p><span class="marginnote">Wilson、Riley、Miyazaki 等后来用不同的均衡概念（预期性、反应）恢复存在性。原文用的是「没有新合同能赚正利润」的静态竞争，结论以不存在闻名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>保单是 \\(( \\alpha,\\beta )\\)：保费与出事时净赔付。无差异曲线在赔偿–保费平面上，单交叉：高风险更愿意为额外保险付钱。零利润线按类型分两条。竞争均衡定义为：每张被选的保单零利润，且不存在新保单在现有合同旁边能赚正利润。</p>',10)),(t(),r(n,null,{default:e(()=>[A(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20POOL%5B%22%E6%B7%B7%E5%90%8C%E4%BF%9D%E5%8D%95%22%5D%20--%3E%20SKIM%5B%22%E6%96%B0%E4%BF%9D%E5%8D%95%E6%8C%96%E8%B5%B0%E4%BD%8E%E9%A3%8E%E9%99%A9%22%5D%0A%20%20SKIM%20--%3E%20NO%5B%22%E6%B7%B7%E5%90%8C%E9%9D%9E%E5%9D%87%E8%A1%A1%22%5D%0A%20%20SEP%5B%22%E5%88%86%E7%A6%BB%3A%20%E9%AB%98%E9%A3%8E%E9%99%A9%E5%85%A8%E4%BF%9D%2C%20%E4%BD%8E%E9%A3%8E%E9%99%A9%E9%83%A8%E5%88%86%E4%BF%9D%22%5D%20--%3E%20CROSS%5B%22%E4%BD%8E%E9%A3%8E%E9%99%A9%E5%BE%88%E5%A4%9A%E6%97%B6%E5%86%8D%E8%A2%AB%E6%B7%B7%E5%90%8C%E6%8C%96%E8%B5%B0%22%5D%0A%20%20CROSS%20--%3E%20EMPTY%5B%22%E5%9D%87%E8%A1%A1%E5%8F%AF%E4%BB%A5%E4%B8%8D%E5%AD%98%E5%9C%A8%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[i(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"与 Spence 的对照：信号博弈里发送者负担教育成本；筛选博弈里扭曲落在低风险的保险数量上（信息租金 / 向下扭曲）。竞争把垄断筛选的利润削到零，却把存在性也削掉。",-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[i("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"机制是合同的奶油撇脂。价格（保费）与数量（保障）必须绑在一起才能分离；只调价格会回到 Akerlof 的平均定价。自由进入使任何留下正利润或交叉补贴的菜单都被攻击。因此「竞争性」与「有均衡」在逆向选择下不再是同一句话——这是原文相对 Debreu 竞争的决裂处。",-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"「奶油撇脂」（cream-skimming）翻译成大白话：新公司不接全部客户，只挑利润最好的低风险者，用一张量身定做的保单挖走，把高风险的烂摊子留给原公司。正因为可以只挑好客，任何靠交叉补贴维持的菜单都守不住。")],-1)),(t(),r(n,null,{default:e(()=>[A(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20HI%5B%22%E9%AB%98%E9%A3%8E%E9%99%A9%E8%80%85%E6%9B%B4%E6%84%BF%E4%B8%BA%E9%A2%9D%E5%A4%96%E4%BF%9D%E9%9A%9C%E4%BB%98%E9%92%B1%EF%BC%9A%E5%8D%95%E4%BA%A4%E5%8F%89%22%5D%20--%3E%20GAP%5B%22%E4%BD%8E%E9%A3%8E%E9%99%A9%E4%BF%9D%E5%8D%95%E6%95%85%E6%84%8F%E7%95%99%E4%BF%9D%E9%9A%9C%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20GAP%20--%3E%20IC%5B%22%E7%BC%BA%E5%8F%A3%E8%AE%A9%E9%AB%98%E9%A3%8E%E9%99%A9%E4%B8%8D%E6%84%BF%E5%81%87%E6%89%AE%E4%BD%8E%E9%A3%8E%E9%99%A9%22%5D%0A%20%20IC%20--%3E%20SELF%5B%22%E6%8A%95%E4%BF%9D%E4%BA%BA%E8%87%AA%E9%80%89%E5%8D%B3%E8%87%AA%E6%88%91%E6%9A%B4%E9%9C%B2%E7%B1%BB%E5%9E%8B%22%5D%0A%20%20SELF%20--%3E%20ZP%5B%22%E4%B8%A4%E5%BC%A0%E4%BF%9D%E5%8D%95%E5%90%84%E8%87%AA%E9%9B%B6%E5%88%A9%E6%B6%A6%22%5D%0A%20%20MANY%5B%22%E4%BD%8E%E9%A3%8E%E9%99%A9%E4%BA%BA%E6%95%B0%E8%B6%B3%E5%A4%9F%E5%A4%9A%E6%97%B6%22%5D%20--%3E%20POOL%5B%22%E8%BF%91%E6%B7%B7%E5%90%8C%E5%90%88%E5%90%8C%E5%8F%AF%E6%8C%96%E8%A7%92%E4%BD%8E%E9%A3%8E%E9%99%A9%22%5D%0A%20%20POOL%20--%3E%20EMPTY%5B%22%E5%88%86%E7%A6%BB%E4%B9%9F%E5%A4%B1%E5%AE%88%EF%BC%8C%E5%9D%87%E8%A1%A1%E5%8F%AF%E7%A9%BA%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[i(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=s('<p>政府或行业可以强制混同（社会保障、社区定价），用存在性换效率：低风险被迫补贴。原文把这一点写成政策含义，不是附录外的道德。</p><h3 id="竞争筛选-vs-垄断筛选" tabindex="-1">竞争筛选 vs 垄断筛选 <a class="header-anchor" href="#竞争筛选-vs-垄断筛选" aria-label="Permalink to &quot;竞争筛选 vs 垄断筛选&quot;">​</a></h3><p>主干<a href="/econ/screening-rent">筛选</a>在委托人框架下谈信息租金。RS 把委托人换成自由进入的保险公司，利润削到零，存在性也可以空。显示原理仍适用，但自由进入不是一个委托人。Wilson / Riley 的反应均衡是后继概念，不写进 1976 年定理。</p><p><span class="marginnote">Rothschild and Stiglitz, <em>QJE</em> 90(4), 1976, 629–649。事故概率是类型，不是隐藏努力。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把「RS 均衡不存在」说成保险市场经验上崩溃。现实有强制投保、分类定价、长期合同与资本监管，均衡概念也已替换。附录对照的是 1976 年那套定义下的定理。也不要把本文写成道德风险：事故概率是类型，不是隐藏努力；隐藏努力是 Holmström 一线，主干道德风险课另写。</p><p><span class="marginnote">常见误区：「RS 均衡可能不存在」不是说现实里买不到保险，也不是说市场必然崩溃。它是在「自由进入＋静态竞争＋只见保单不见类型」这套定义下的逻辑结论；现实中的强制投保、团体险、长期合同，都是绕开空均衡的制度补丁。</span></p><p>微观信息附录到此为止。下一篇转到宏观：Keynes《通论》的问题设定。</p><p>混同不是均衡，因为可被只吸引低风险的合同打破。分离在高风险足够多时可以站住。</p><p>无均衡不是「保险市场经验上不存在」。原文是特定均衡概念下的逻辑可能性。强制混同、社区评级是制度回应。</p><p>隐藏类型不是隐藏努力。道德风险保险（免赔额、努力）是 Holmström 一线，主干另写。</p><p>竞争把垄断筛选的利润削到零，也可以把存在性削掉。这是相对 Debreu 竞争的决裂，不是技术故障。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Rothschild–Stiglitz 1976：竞争保险里混同非均衡，分离可空。</li><li>筛选用保障数量扭曲来分离；自由进入可破坏存在。</li><li>与 Spence 分工：接收者菜单 vs 发送者信号。</li><li>出处：Rothschild and Stiglitz, <em>QJE</em> 1976。</li></ul>',14))])}const f=o(d,[["render",h]]);export{C as __pageData,f as default};
